-- ------------------------------------------------------
-- Table: articles
-- ------------------------------------------------------
DROP TABLE IF EXISTS `articles`;
CREATE TABLE `articles` (
  `id` varchar(191) NOT NULL,
  `title` varchar(255) NOT NULL,
  `slug` varchar(255) NOT NULL,
  `excerpt` text NOT NULL,
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`content`)),
  `coverImage` text DEFAULT NULL,
  `category` varchar(100) NOT NULL,
  `tags` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`tags`)),
  `authorId` varchar(255) NOT NULL,
  `status` enum('DRAFT','PUBLISHED') NOT NULL DEFAULT 'DRAFT',
  `isFeatured` tinyint(1) NOT NULL DEFAULT 0,
  `seo` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`seo`)),
  `publishedAt` datetime(3) DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `articles_slug_key` (`slug`),
  KEY `articles_status_publishedAt_idx` (`status`,`publishedAt`),
  KEY `articles_category_status_idx` (`category`,`status`),
  KEY `articles_slug_idx` (`slug`),
  KEY `articles_authorId_idx` (`authorId`),
  CONSTRAINT `articles_authorId_fkey` FOREIGN KEY (`authorId`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `articles` (`id`, `title`, `slug`, `excerpt`, `content`, `coverImage`, `category`, `tags`, `authorId`, `status`, `isFeatured`, `seo`, `publishedAt`, `createdAt`, `updatedAt`) VALUES
('6ab6ec8f4a1645df61a96b27', 'ليه JWT؟ كل اللي محتاج تعرفه عن JSON Web Token', 'ليه-jwt-كل-اللي-محتاج-تعرفه-عن-json-web-token', 'إيه هو JWT وليه بنستخدمه؟ شرح JSON Web Token بالبلدي، من Authentication وAuthorization لحد Access Token وRefresh Token وطريقة استخدامه مع React وNode.js.', '{"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "marks": [{"type": "bold"}], "text": "ليه JWT؟ كل اللي محتاج تعرفه عن JSON Web Token"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "لو بتشتغل في تطوير الويب، وخصوصًا في الـ Backend أو الـ Full Stack، فأكيد قابلت مصطلح اسمه "}, {"type": "text", "marks": [{"type": "bold"}], "text": "JWT"}, {"type": "text", "text": "."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "ممكن تكون شوفته في مشروع React مع Node.js، أو وأنت بتعمل Login وRegister، أو وأنت بتتعامل مع REST API، أو حتى وأنت بتقرأ عن Authentication وAuthorization."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "لكن السؤال اللي بييجي في دماغ ناس كتير:"}]}, {"type": "paragraph", "content": [{"type": "text", "marks": [{"type": "bold"}], "text": "ليه أصلًا بنستخدم JWT؟"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "يعني إيه المشكلة اللي JWT جه يحلها؟"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "وليه لما المستخدم يعمل Login، السيرفر ما يكتفيش إنه يعرف إن المستخدم سجل دخوله وخلاص؟"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "وإيه اللي بيحصل من لحظة ما المستخدم يكتب الـ Email والـ Password لحد ما يقدر يفتح Dashboard محمية؟"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "في المقالة دي هنتكلم عن JWT من البداية خالص، وهنفهمه بطريقة بسيطة، من غير تعقيد، وفي نفس الوقت هنغطي التفاصيل المهمة اللي أي Full Stack Developer محتاج يفهمها."}]}, {"type": "horizontalRule"}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "الأول يعني إيه Authentication؟"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "قبل ما نفهم JWT، لازم نفهم المشكلة اللي بنحاول نحلها."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "عندنا حاجة اسمها "}, {"type": "text", "marks": [{"type": "bold"}], "text": "Authentication"}, {"type": "text", "text": "."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "ببساطة جدًا:"}]}, {"type": "paragraph", "content": [{"type": "text", "marks": [{"type": "bold"}], "text": "Authentication يعني أتأكد إن أنت فعلًا الشخص اللي بتقول إنك هو."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "مثلًا لما تدخل موقع وتكتب:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Email"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Password"}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "السيرفر بياخد البيانات دي ويروح يتأكد منها."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "لو البيانات صحيحة، السيرفر يعرف إن المستخدم ده فعلًا صاحب الحساب."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "وهنا نقول:"}]}, {"type": "paragraph", "content": [{"type": "text", "marks": [{"type": "bold"}], "text": "المستخدم اتعمله Authentication."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "يعني السيرفر عرف أنت مين."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "لكن هنا عندنا مشكلة مهمة جدًا."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "طيب المستخدم عمل Login مرة."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "إزاي السيرفر هيعرف في الطلب الجاي إن ده نفس المستخدم اللي عمل Login؟"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "لأن HTTP بطبيعته "}, {"type": "text", "marks": [{"type": "bold"}], "text": "Stateless"}, {"type": "text", "text": "."}]}, {"type": "horizontalRule"}, {"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "يعني إيه Stateless؟"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "الـ HTTP Request مستقل عن اللي قبله."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "يعني لما تعمل Request:"}]}, {"type": "codeBlock", "attrs": {"language": null}, "content": [{"type": "text", "text": "GET /api/profile"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "السيرفر مش لازم يكون فاكر إن نفس الشخص ده عمل Login من 5 دقايق."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "بالنسبة للسيرفر، ده Request جديد."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "فلازم المستخدم يبعث حاجة مع كل Request تثبت إنه بالفعل مستخدم مسجل دخول."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "وهنا بيظهر دور الـ "}, {"type": "text", "marks": [{"type": "bold"}], "text": "Token"}, {"type": "text", "text": "."}]}, {"type": "horizontalRule"}, {"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "طيب يعني إيه Token؟"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "الـ Token ببساطة عبارة عن قيمة بيتم إصدارها للمستخدم بعد تسجيل الدخول."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "تقدر تعتبرها زي:"}]}, {"type": "paragraph", "content": [{"type": "text", "marks": [{"type": "bold"}], "text": "بطاقة مؤقتة بتقول للسيرفر: أنا المستخدم اللي عمل Login قبل كده."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "مثلًا المستخدم يعمل Login:"}]}, {"type": "codeBlock", "attrs": {"language": null}, "content": [{"type": "text", "text": "POST /api/login"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "ويبعت:"}]}, {"type": "codeBlock", "attrs": {"language": null}, "content": [{"type": "text", "text": "{\\n  \\"email\\": \\"rabea@example.com\\",\\n  \\"password\\": \\"123456\\"\\n}"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "السيرفر يتأكد إن البيانات صحيحة."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "بعدها السيرفر يعمل Token ويرجعه للمستخدم."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "بعد كده المستخدم يستخدم الـ Token ده مع الـ Requests المحمية."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "مثلًا:"}]}, {"type": "codeBlock", "attrs": {"language": null}, "content": [{"type": "text", "text": "GET /api/profile\\nAuthorization: Bearer TOKEN"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "السيرفر يقرأ الـ Token ويتأكد منه."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "لو صحيح:"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "يسمح للمستخدم يدخل."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "لو غلط أو منتهي:"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "يرفض الـ Request."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "وهنا وصلنا لـ JWT."}]}, {"type": "horizontalRule"}, {"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "طيب JWT يعني إيه؟"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "JWT اختصار لـ:"}]}, {"type": "paragraph", "content": [{"type": "text", "marks": [{"type": "bold"}], "text": "JSON Web Token"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "وهو Standard بيستخدم لنقل معلومات بين طرفين بطريقة يمكن التحقق من صحتها باستخدام Signature."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "وأهم حاجة تفهمها:"}]}, {"type": "paragraph", "content": [{"type": "text", "marks": [{"type": "bold"}], "text": "JWT مش مجرد Password بديلة."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "ومش معناها إن البيانات الموجودة جواها متشفرة."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "ودي نقطة ناس كتير بتتلخبط فيها."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "الـ JWT غالبًا بيكون:"}]}, {"type": "codeBlock", "attrs": {"language": null}, "content": [{"type": "text", "text": "Header.Payload.Signature"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "يعني 3 أجزاء منفصلين بنقطة."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "مثلًا:"}]}, {"type": "codeBlock", "attrs": {"language": null}, "content": [{"type": "text", "text": "xxxxx.yyyyy.zzzzz"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "كل جزء له وظيفة معينة."}]}, {"type": "horizontalRule"}, {"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "مكونات JWT"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "الـ JWT بيتكون من:"}]}, {"type": "orderedList", "attrs": {"start": 1, "type": null}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Header"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Payload"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Signature"}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "تعالى نفهم كل واحد."}]}, {"type": "horizontalRule"}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "أول جزء: Header"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "الـ Header بيحتوي على معلومات عن الـ Token نفسه."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "مثلًا:"}]}, {"type": "codeBlock", "attrs": {"language": null}, "content": [{"type": "text", "text": "{\\n  \\"alg\\": \\"HS256\\",\\n  \\"typ\\": \\"JWT\\"\\n}"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "هنا عندنا:"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "typ"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "يعني نوع الـ Token."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "وغالبًا بيكون:"}]}, {"type": "codeBlock", "attrs": {"language": null}, "content": [{"type": "text", "text": "JWT"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "te