k", "attrs": {"language": "text"}, "content": [{"type": "text", "text": "HTTP\\n↓\\nRequest / Response\\n↓\\nCookies\\n↓\\nSessions\\n↓\\nAuthentication\\n↓\\nAuthorization\\n↓\\nPassword Hashing\\n↓\\nJWT\\n↓\\nRBAC\\n↓\\nOAuth\\n↓\\nWeb Security\\n"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "ومتبدأش مباشرة بـ JWT من غير ما تفهم أساسيات HTTP والـ Cookies والـ Sessions."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "لأنك ممكن تحفظ الكود من غير ما تفهم هو بيعمل إيه."}]}, {"type": "horizontalRule"}, {"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "Authentication وAuthorization في مشروع MERN"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "لو بتشتغل:"}]}, {"type": "codeBlock", "attrs": {"language": "text"}, "content": [{"type": "text", "text": "MongoDB\\nExpress\\nReact\\nNode.js\\n"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "فممكن تبني النظام بالشكل التالي:"}]}, {"type": "codeBlock", "attrs": {"language": "text"}, "content": [{"type": "text", "text": "React\\n  |\\n  ↓\\nExpress API\\n  |\\n  ↓\\nAuthentication Middleware\\n  |\\n  ↓\\nAuthorization Middleware\\n  |\\n  ↓\\nController\\n  |\\n  ↓\\nMongoDB\\n"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "مثلًا:"}]}, {"type": "codeBlock", "attrs": {"language": "text"}, "content": [{"type": "text", "text": "POST /auth/login\\n"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "لتسجيل الدخول."}]}, {"type": "codeBlock", "attrs": {"language": "text"}, "content": [{"type": "text", "text": "GET /users/me\\n"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "للحصول على بيانات المستخدم الحالي."}]}, {"type": "codeBlock", "attrs": {"language": "text"}, "content": [{"type": "text", "text": "GET /admin/users\\n"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "للمستخدمين المصرح لهم."}]}, {"type": "codeBlock", "attrs": {"language": "text"}, "content": [{"type": "text", "text": "DELETE /admin/users/:id\\n"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "للمستخدمين الذين يمتلكون صلاحية الحذف."}]}, {"type": "horizontalRule"}, {"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "مثال عملي على الـ Middleware"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "ممكن يكون عندك:"}]}, {"type": "codeBlock", "attrs": {"language": "javascript"}, "content": [{"type": "text", "text": "router.get(\\n  \\"/admin/users\\",\\n  authenticate,\\n  authorize(\\"ADMIN\\"),\\n  getUsers\\n);\\n"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "الطلب يمر بالمراحل دي:"}]}, {"type": "codeBlock", "attrs": {"language": "text"}, "content": [{"type": "text", "text": "Request\\n   ↓\\nauthenticate\\n   ↓\\nIs user authenticated?\\n   ↓\\nauthorize\\n   ↓\\nIs user ADMIN?\\n   ↓\\nController\\n"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "لو أي خطوة فشلت، الطلب يتم رفضه."}]}, {"type": "horizontalRule"}, {"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "Authentication مش معناها Authorization"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "خلينا نثبتها للمرة الأخيرة."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "لو عملت Login:"}]}, {"type": "codeBlock", "attrs": {"language": "text"}, "content": [{"type": "text", "text": "Authentication\\n"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "لو دخلت لوحة التحكم لأنك Admin:"}]}, {"type": "codeBlock", "attrs": {"language": "text"}, "content": [{"type": "text", "text": "Authorization\\n"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "لو الموقع عرف إنك ربيع:"}]}, {"type": "codeBlock", "attrs": {"language": "text"}, "content": [{"type": "text", "text": "Authentication\\n"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "لو الموقع سمح لك تحذف مستخدم:"}]}, {"type": "codeBlock", "attrs": {"language": "text"}, "content":