DROP TABLE IF EXISTS `videos`;
CREATE TABLE `videos` (
  `id` varchar(191) NOT NULL,
  `title` varchar(255) NOT NULL,
  `description` text DEFAULT NULL,
  `platform` enum('YOUTUBE','TIKTOK') NOT NULL DEFAULT 'YOUTUBE',
  `url` text NOT NULL,
  `thumbnail` text DEFAULT NULL,
  `status` enum('DRAFT','PUBLISHED') NOT NULL DEFAULT 'DRAFT',
  `authorId` varchar(255) NOT NULL,
  `publishedAt` datetime(3) DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `videos_status_publishedAt_idx` (`status`,`publishedAt`),
  KEY `videos_status_platform_publishedAt_idx` (`status`,`platform`,`publishedAt`),
  KEY `videos_authorId_idx` (`authorId`),
  CONSTRAINT `videos_authorId_fkey` FOREIGN KEY (`authorId`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

