#برمجة #تعلم_البرمجة #Programming #Coding #Frontend #Backend #FullStack #JavaScript #WebDevelopment #Shorts', 'YOUTUBE', 'https://www.youtube.com/shorts/vfkUirn_KnQ', 'https://pub-f9f474a915314796ac71ef9e5b4b78a0.r2.dev/articles/1790770865928-af45f6cf33132cf4ad35df18f51cfa22.png', 'PUBLISHED', '6ab5382b511dee55f980235a', '2026-10-01T18:42:17.472Z', '2026-10-01T18:42:17.472Z', '2026-10-02T13:27:59.008Z'),
('6abfb205a73d450d02072be5', 'يعني إيه كمبيوتر؟ CPU وRAM وSSD وGPU ببساطة أساسيات الكمبيوتر للمبتدئين #0', 'في أول فيديو من سلسلة أساسيات الكمبيوتر وWindows للمبتدئين من خمسة برمجة بالبلدي، هنبدأ من الصفر وهنفهم الكمبيوتر بطريقة بسيطة ومن غير تعقيد.', 'YOUTUBE', 'https://www.youtube.com/watch?v=9quqWXxdifI&list=PLYMsJ3Zl5HO4&index=1&t=23s&pp=iAQB', 'https://i.ytimg.com/vi/9quqWXxdifI/hqdefault.jpg?sqp=-oaymwEnCNACELwBSFryq4qpAxkIARUAAIhCGAHYAQHiAQoIGBACGAY4AUAB&rs=AOn4CLB1sSCozX_01Md4nJLaQ8Yp3mJjkw', 'DRAFT', '6ab676b7db2a3194c7928d08', NULL, '2026-10-02T13:30:45.304Z', '2026-10-02T13:30:45.304Z');

