DROP TABLE IF EXISTS `featured_links`;
CREATE TABLE `featured_links` (
  `id` varchar(191) NOT NULL,
  `title` varchar(255) NOT NULL,
  `image` text NOT NULL,
  `url` text NOT NULL,
  `badge` varchar(100) DEFAULT '',
  `description` text DEFAULT '',
  `ctaText` varchar(100) DEFAULT '',
  `order` int(11) NOT NULL DEFAULT 0,
  `isActive` tinyint(1) NOT NULL DEFAULT 1,
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `featured_links_isActive_order_createdAt_idx` (`isActive`,`order`,`createdAt`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `featured_links` (`id`, `title`, `image`, `url`, `badge`, `description`, `ctaText`, `order`, `isActive`, `createdAt`, `updatedAt`) VALUES
