-- ------------------------------------------------------
-- Table: settings
-- ------------------------------------------------------
DROP TABLE IF EXISTS `settings`;
CREATE TABLE `settings` (
  `id` varchar(191) NOT NULL,
  `siteName` varchar(255) NOT NULL DEFAULT 'خمسة برمجة بالبلدي',
  `tagline` varchar(255) NOT NULL DEFAULT 'افهمها بالبلدي.. اكتبها بالكود.',
  `siteDescription` text NOT NULL,
  `language` varchar(10) NOT NULL DEFAULT 'ar',
  `direction` varchar(10) NOT NULL DEFAULT 'rtl',
  `timezone` varchar(50) NOT NULL DEFAULT 'Africa/Cairo',
  `logo` text DEFAULT NULL,
  `favicon` text DEFAULT NULL,
  `socialLinks` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`socialLinks`)),
  `contact` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`contact`)),
  `defaultSeo` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`defaultSeo`)),
  `homepage` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`homepage`)),
  `hero` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`hero`)),
  `about` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`about`)),
  `founder` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`founder`)),
  `footer` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`footer`)),
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `settings` (`id`, `siteName`, `tagline`, `siteDescription`, `language`, `direction`, `timezone`, `logo`, `favicon`, `socialLinks`, `contact`, `defaultSeo`, `homepage`, `hero`, `about`, `founder`, `footer`, `createdAt`, `updatedAt`) VALUES
('6ab5382c511dee55f980235d', 'خمسة برمجة بالبلدي', 'افهمها بالبلدي.. اكتبها بالكود.', 'منصة لتبسيط البرمجة وعلوم الحاسب باللغة العربية البسيطة', 'ar', 'rtl', 'Africa/Cairo', 'https://pub-f9f474a915314796ac71ef9e5b4b78a0.r2.dev/articles/1790619346465-62997bab9e822779a46d91f8d60f4560.png', 'https://pub-f9f474a915314796ac71ef9e5b4b78a0.r2.dev/articles/1790619346465-62997bab9e822779a46d91f8d60f4560.png', '{"tiktok": "https://www.tiktok.com/@5programming.balady", "youtube": "https://www.youtube.com/@5barmhttps://www.youtube.com/@5programming.baladyaga", "facebook": "", "github": "", "linkedin": "", "whatsapp": "", "email": "", "phone": ""}', '{"email": "r.shaban.2016@gmail.com", "phone": "01156807072", "whatsapp": "01156807072", "contactMessage": ""}', '{"title": "", "description": "مقالات وفيديوهات حصرية لشرح مفاهيم البرمجة وتطوير الويب ببساطة", "keywords": ["برمجة", "javascript", "typescript", "خمسة برمجة بالبلدي", "nodejs", "ثص"], "ogTitle": "", "ogDescription": "", "ogImage": "https://pub-f9f474a915314796ac71ef9e5b4b78a0.r2.dev/articles/1790619346465-62997bab9e822779a46d91f8d60f4560.png", "canonicalUrl": ""}', '{"showHero": true, "showWhyKhamsa": true, "showPhilosophy": true, "showFounder": true, "showServices": true, "showArticles": true, "showVideos": true, "showSocial": true, "showFinalCTA": true}', '{"heroTitle": "خمسة برمجة بالبلدي", "heroSubtitle": "افهمها بالبلدي.. اكتبها بالكود.", "heroDescription": "منصة عربية لتبسيط البرمجة والتكنولوجيا، نشرح فيها الفكرة قبل الكود، ونحوّل المفاهيم المعقدة إلى محتوى واضح وعملي يساعدك تتعلم وتطبّق وتطوّر نفسك.", "primaryButtonText": "اكتشف المقالات", "primaryButtonUrl": "/articles", "secondaryButtonText": "شاهد المحتوى", "secondaryButtonUrl": "/videos"}', '{"aboutTitle": "من نحن؟", "aboutShortDescription": "بدأت بفكرة بسيطة... إن البرمجة ممكن تتفهم بشكل أبسط.", "aboutStory": "ليه ناس كتير عندها الرغبة الحقيقية تتعلم البرمجة، لكن أول ما تبدأ تواجه مصطلحات معقدة وشروحات طويلة ومحتوى مش مناسب لطريقة تفكيرها؟ من هنا بدأت الفكرة: ليه ما نشرحش البرمجة بطريقة بسيطة، من غير ما نبسطها لدرجة تفقد قيمتها وعمقها الهندسي؟", "aboutMission": "تقديم محتوى تقني عربي عالي الجودة يركز على الفهم العميق للأساسيات قبل كتابة الكود.", "aboutVision": "بناء جيل من المطورين العرب يمتلكون عقلية التفكير الهندسي السليم والقدرة على حل المشكلات.", "aboutGoal": "مساعدة كل مبرمج عربي على الانتقال من مرحلة الحفظ والتقليد إلى مرحلة الفهم والابتكار.", "aboutMessage": "«مش هنخلي البرمجة سهلة... هنخلي فهمها أسهل.»"}', '{"founderName": "ربيع شعبان", "founderRole": "Full Stack Software Engineer & Content Creator", "founderBio": "مهندس برمجيات ومطور شغوف بتبسيط مفاهيم البرمجة وهندسة البرمجيات باللغة العربية بأسلوب عملي يركز على الفهم والتطبيق.", "founderImage": "https://pub-f9f474a915314796ac71ef9e5b4b78a0.r2.dev/settings/1790342553596-c3b0b3ad4e5a7544e8cfdb149652b335.png", "founderLinkedIn": "https://linkedin.com", "founderGitHub": "https://github.com"}', '{"footerDescription": "افهمها بالبلدي.. اكتبها بالكود. منصة عربية لتبسيط علوم الحاسب وهندسة البرمجيات.", "footerCopyright": "© 2026 خمسة برمجة بالبلدي. جميع الحقوق محفوظة.", "footerShowSocials": true, "footerShowNavigation": true}', '2026-09-24T14:48:12.107Z', '2026-10-02T13:52:47.292Z');

